import{_ as s,a0 as a,w as r,s as u,ao as p,I as l,x as e,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 15.04 上安裝帶 JSON 支持的 SQLite 3.9.1 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 15.04 上安裝帶 JSON 支持的 SQLite 3.9.1 | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 15.04 上安裝帶 JSON 支持的 SQLite 3.9.1 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 15.04 上安裝帶 JSON 支持的 SQLite 3.9.1 | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20151104 How to Install SQLite 3.9.1 with JSON Support on Ubuntu 15.04","title":"如何在 Ubuntu 15.04 上安裝帶 JSON 支持的 SQLite 3.9.1","tag":"201602","desc":""},"relativePath":"201602/20151104 How to Install SQLite 3.9.1 with JSON Support on Ubuntu 15.04.md","filePath":"[post].md"}'),d={name:"201602/20151104 How to Install SQLite 3.9.1 with JSON Support on Ubuntu 15.04.md"};function S(_,t,L,g,b,m){const i=a("Link");return r(),u("div",null,[t[16]||(t[16]=p(`<h1 id="如何在-ubuntu-15-04-上安裝帶-json-支持的-sqlite-3-9-1" tabindex="-1">如何在 Ubuntu 15.04 上安裝帶 JSON 支持的 SQLite 3.9.1 <a class="header-anchor" href="#如何在-ubuntu-15-04-上安裝帶-json-支持的-sqlite-3-9-1" aria-label="Permalink to “如何在 Ubuntu 15.04 上安裝帶 JSON 支持的 SQLite 3.9.1”">​</a></h1><p>歡迎閲讀我們關於SQLite 的文章，SQLite 是當今世界上使用最廣泛的 SQL 資料庫引擎，它基本不需要配置，不需要設置或管理就可以運行。SQLite 是一個是開放領域（public-domain）的軟件，是一個關係型資料庫管理系統（RDBMS），用來在一個大數據表中存儲用户定義的記錄。對於數據存儲和管理來説，資料庫引擎要處理複雜的查詢命令，這些命令可能會從多個表獲取數據然後生成報告和數據總結。</p><p>SQLite 是一個非常小、輕量級，不需要獨立的服務進程或系統。它可以運行在 UNIX，Linux，Mac OS-X，Android，iOS 和 Windows 上，已經被大量的軟件程序使用，如 Opera, Ruby On Rails, Adobe System, Mozilla Firefox, Google Chrome 和 Skype。</p><h3 id="_1-基本需求" tabindex="-1">1) 基本需求: <a class="header-anchor" href="#_1-基本需求" aria-label="Permalink to “1) 基本需求:”">​</a></h3><p>在絕大部分支持 SQLite 的平台上安裝 SQLite 基本上並沒有複雜的要求。</p><p>讓我們在 CLI 或者 Secure Shell 上使用 sudo 或者 root 權限登錄 Ubuntu 服務器。然後更新系統，這樣子就可以讓操作系統的軟件更新到新版本。</p><p>在 Ubuntu 上，使用如下的命令來更新系統的軟件源。</p><pre><code># apt-get update
</code></pre><p>如果你要在新安裝的 Ubuntu 上部署 SQLite，那麼你需要安裝一些基礎的系統管理工具，如 wget, make, unzip, gcc。</p><p>要安裝 wget，可以使用下面的命令，如果系統提示的話，輸入 Y ：</p><pre><code># apt-get install wget make gcc
</code></pre><h3 id="_2-下載-sqlite" tabindex="-1">2) 下載 SQLite <a class="header-anchor" href="#_2-下載-sqlite" aria-label="Permalink to “2) 下載 SQLite”">​</a></h3>`,12)),l("p",null,[t[1]||(t[1]=e("要下載 SQLite ，最好是在 ",-1)),o(i,{href:"https://www.sqlite.org/download.html"},{default:n(()=>[...t[0]||(t[0]=[e("SQLite 官網",-1)])]),_:1}),t[2]||(t[2]=e("下載，如下所示",-1))]),t[17]||(t[17]=p(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/Selection_014.png" alt="SQLite download"></p><p>你也可以直接複製資源的連接然後在命令列使用 wget 下載，如下所示：</p><pre><code># wget https://www.sqlite.org/2015/sqlite-autoconf-3090100.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/23.png" alt="wget SQLite"></p><p>下載完成之後，解壓縮安裝包，切換工作目錄到解壓縮後的 SQLite 目錄，使用下面的命令。</p><pre><code># tar -zxvf sqlite-autoconf-3090100.tar.gz
</code></pre><h3 id="_3-安裝-sqlite" tabindex="-1">3) 安裝 SQLite <a class="header-anchor" href="#_3-安裝-sqlite" aria-label="Permalink to “3) 安裝 SQLite”">​</a></h3><p>現在我們要開始安裝、配置剛才下載的 SQLite。在 Ubuntu 上編譯、安裝 SQLite，運行配置腳本：</p><pre><code>root@ubuntu-15:~/sqlite-autoconf-3090100# ./configure –prefix=/usr/local
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/35.png" alt="SQLite Installation"></p><p>配置要上面的安裝位置前綴（prefix）之後，運行下面的命令編譯安裝包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu-15:~/sqlite-autoconf-3090100# make</span></span>
<span class="line"><span>source=&#39;sqlite3.c&#39; object=&#39;sqlite3.lo&#39; libtool=yes \\</span></span>
<span class="line"><span>DEPDIR=.deps depmode=none /bin/bash ./depcomp \\</span></span>
<span class="line"><span>/bin/bash ./libtool --tag=CC --mode=compile gcc -DPACKAGE_NAME=\\&quot;sqlite\\&quot; -DPACKAGE_TARNAME=\\&quot;sqlite\\&quot; -DPACKAGE_VERSION=\\&quot;3.9.1\\&quot; -DPACKAGE_STRING=\\&quot;sqlite\\ 3.9.1\\&quot; -DPACKAGE_BUGREPORT=\\&quot;http://www.sqlite.org\\&quot; -DPACKAGE_URL=\\&quot;\\&quot; -DPACKAGE=\\&quot;sqlite\\&quot; -DVERSION=\\&quot;3.9.1\\&quot; -DSTDC_HEADERS=1 -DHAVE_SYS_TYPES_H=1 -DHAVE_SYS_STAT_H=1 -DHAVE_STDLIB_H=1 -DHAVE_STRING_H=1 -DHAVE_MEMORY_H=1 -DHAVE_STRINGS_H=1 -DHAVE_INTTYPES_H=1 -DHAVE_STDINT_H=1 -DHAVE_UNISTD_H=1 -DHAVE_DLFCN_H=1 -DLT_OBJDIR=\\&quot;.libs/\\&quot; -DHAVE_FDATASYNC=1 -DHAVE_USLEEP=1 -DHAVE_LOCALTIME_R=1 -DHAVE_GMTIME_R=1 -DHAVE_DECL_STRERROR_R=1 -DHAVE_STRERROR_R=1 -DHAVE_POSIX_FALLOCATE=1 -I. -D_REENTRANT=1 -DSQLITE_THREADSAFE=1 -DSQLITE_ENABLE_FTS3 -DSQLITE_ENABLE_RTREE -g -O2 -c -o sqlite3.lo sqlite3.c</span></span></code></pre></div><p>運行完上面的命令之後，要在 Ubuntu 上完成 SQLite 的安裝得運行下面的命令。</p><pre><code># make install
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/44.png" alt="SQLite Make Install"></p><h3 id="_4-測試-sqlite-安裝" tabindex="-1">4) 測試 SQLite 安裝 <a class="header-anchor" href="#_4-測試-sqlite-安裝" aria-label="Permalink to “4) 測試 SQLite 安裝”">​</a></h3><p>要保證 SQLite 3.9 安裝成功了，運行下面的命令。</p><pre><code># sqlite3
</code></pre><p>SQLite 的版本會顯示在命令列。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/53.png" alt="Testing SQLite Installation"></p><h3 id="_5-使用-sqlite" tabindex="-1">5) 使用 SQLite <a class="header-anchor" href="#_5-使用-sqlite" aria-label="Permalink to “5) 使用 SQLite”">​</a></h3><p>SQLite 很容易上手。要獲得詳細的使用方法，在SQLite 控制台裏輸入下面的命令。</p><pre><code>sqlite&gt; .help
</code></pre><p>這裏會顯示全部可用的命令和詳細説明。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/62.png" alt="SQLite Help"></p><p>現在開始最後一部分，使用一點 SQLite 命令創建資料庫。</p><p>要創建一個新的資料庫需要運行下面的命令。</p><pre><code># sqlite3 test.db
</code></pre><p>然後創建一張新表。</p><pre><code>sqlite&gt; create table memos(text, priority INTEGER);
</code></pre><p>接着使用下面的命令插入數據。</p><pre><code>sqlite&gt; insert into memos values(&#39;deliver project description&#39;, 15);
sqlite&gt; insert into memos values(&#39;writing new artilces&#39;, 100);
</code></pre><p>要查看插入的數據可以運行下面的命令。</p><pre><code>sqlite&gt; select * from memos;
deliver project description|15
writing new artilces|100
</code></pre><p>或者使用下面的命令離開。</p><pre><code>sqlite&gt; .exit
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/73.png" alt="Using SQLite3"></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>通過本文你可以瞭解如果安裝支持 JSON1 的最新版的 SQLite，SQLite 從 3.9.0 開始支持 JSON1。這是一個非常棒的庫，可以內嵌到應用程序，利用它可以很有效而輕量的管理資源。我們希望你能覺得本文有所幫助，請隨意地向我們反饋你遇到的問題和困難。</p><hr>`,40)),l("p",null,[t[4]||(t[4]=e("via: ",-1)),o(i,{href:"http://linoxide.com/ubuntu-how-to/install-sqlite-json-ubuntu-15-04/"},{default:n(()=>[...t[3]||(t[3]=[e("http://linoxide.com/ubuntu-how-to/install-sqlite-json-ubuntu-15-04/",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=e("作者：",-1)),o(i,{href:"http://linoxide.com/author/kashifs/"},{default:n(()=>[...t[5]||(t[5]=[e("Kashif Siddique",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),o(i,{href:"https://github.com/oska874"},{default:n(()=>[...t[6]||(t[6]=[e("oska874",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:n(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=e("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:n(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const h=s(d,[["render",S]]);export{T as __pageData,h as default};
